import json,re
from pathlib import Path
root=Path(__file__).resolve().parents[1]
sources=json.loads((root/'source-content/pages.json').read_text()); source={x['path']:x for x in sources}
manifest=json.loads((root/'source-content/assets-manifest.json').read_text())
routes=json.loads((root/'source-content/route-map.json').read_text())
def image(path):
 return next((Path(x['local_file']).name for x in manifest if x['used_on']==[path] and x['local_file'].endswith('.png')), 'c59dfcc54a09.png')
def faq(path):
 b=next((b['text'] for b in source[path]['blocks'] if b['type']=='668'),'')
 sentences=re.split(r'(?<=[.!?])\s+(?=[А-ЯЁ])',b); result=[]
 for sentence in sentences:
  if '?' in sentence:
   q,_,a=sentence.partition('?');result.append({'q':q+'?','a':a.strip()})
  elif result: result[-1]['a']+=' '+sentence
 return result
products=[
('/li-ion','Литий-ионные аккумуляторы','Li-ion','Высокая плотность энергии для портативной электроники, транспорта и энергосистем.','Литий-ионные аккумуляторы — перезаряжаемые батареи, в которых ионы лития перемещаются между электродами при заряде и разряде. Высокая энергетическая плотность позволяет получить больше энергии при меньших размерах и весе.',['Высокая энергетическая плотность','Низкий саморазряд при хранении','Отсутствие эффекта памяти','Разработка под ваше техническое задание']),
('/li-pol','Литий-полимерные аккумуляторы','Li-pol','Компактные и лёгкие батареи для устройств с ограниченным пространством.','Литий-полимерные аккумуляторы применяются в мобильных устройствах, дронах и компактной электронике. Полимерный электролит позволяет создавать тонкие батареи различных форм и размеров.',['Различные формы и габариты','Малый вес и толщина','Низкий саморазряд','Высокая ёмкость при компактных размерах']),
('/lifepo4','Литий-железо-фосфатные аккумуляторы','LiFePO4','Стабильное питание для транспорта, промышленности и накопления энергии.','LiFePO4 аккумуляторы отличаются стабильностью химического состава и длительным сроком службы. Применяются в электромобилях, солнечных системах и промышленном оборудовании.',['Стабильность и безопасность','Устойчивость к циклическим нагрузкам','Длительный срок эксплуатации','Подбор для систем хранения энергии']),
('/lto','Литий-титанатные аккумуляторы','LTO','Решения для интенсивных циклов, быстрой зарядки и сложных условий.','В литий-титанатных аккумуляторах используется литий-титанатный анод. Эта технология подходит для систем с частыми циклами заряда и разряда, электротранспорта и специализированного оборудования.',['Быстрая зарядка','Большой ресурс циклов','Работа в широком диапазоне температур','Устойчивость к нагрузкам']),
('/chargers','Зарядные устройства','Зарядные устройства','Подбор зарядного устройства под химию и параметры аккумулятора.','Правильное зарядное устройство обеспечивает безопасный режим заряда и стабильную работу батареи. LifeBatt подбирает устройства для Li-ion, Li-pol, LiFePO4 и LTO с учётом совместимости.',['Регулирование тока и напряжения','Защита от перегрева и короткого замыкания','Подбор по типу и ёмкости батареи','Индикация процесса заряда']),
('/bms','Платы управления батареей','BMS','Контроль, защита и балансировка элементов аккумуляторной батареи.','BMS (Battery Management System) — электронный модуль управления аккумуляторной батареей. Он контролирует её работу, защищает ячейки и помогает поддерживать рабочие параметры системы.',['Защита от перезаряда и переразряда','Балансировка ячеек','Защита от короткого замыкания','Мониторинг напряжения, тока и температуры']),
('/solutions','Готовые аккумуляторные батареи','Готовые решения','Собранные и протестированные батареи для ваших устройств и систем.','Полностью собранные и протестированные аккумуляторные батареи экономят время на разработку. Доступны направления на основе Li-ion, Li-pol, LiFePO4 и LTO; конкретное исполнение подбирается по задаче.',['Различные ёмкости и напряжения','Контроль и тестирование батарей','Система управления BMS','Поддержка при интеграции']),
('/solutions-bla','Аккумуляторные решения для БПЛА','Решения для БПЛА','Аккумуляторы для беспилотных летательных аппаратов и мультикоптеров.','Разработанные и собранные аккумуляторы для беспилотных устройств. При подборе учитываются масса батареи, энергопотребление оборудования и необходимое время работы.',['Высокая энергетическая плотность','Низкий саморазряд','Отсутствие эффекта памяти','Подбор под беспилотное устройство'])]
entries=[]
for path,title,short,lead,body,benefits in products:
 entries.append(dict(path=path,title=title,short=short,kind='product',image=image(path),lead=lead,body=body,benefits=benefits,faq=faq(path),group='Аккумуляторы' if path in ['/li-ion','/li-pol','/lifepo4','/lto'] else 'Компоненты' if path in ['/bms','/chargers'] else 'Готовые решения'))
groups={'warehouse_and_cleaning':'Промышленность','multicopters':'Транспорт','radios':'Связь и безопасность','water_transport':'Транспорт','medical':'Специальное оборудование','electric_cars':'Транспорт','solar_power':'Энергетика','wheelchairs':'Транспорт','alarmsystems':'Связь и безопасность','telecommunication':'Связь и безопасность','ups':'Энергетика','mobility':'Транспорт','gas_and_oil':'Промышленность','military_industry':'Специальное оборудование'}
for slug,group in groups.items():
 path='/'+slug;title=next(x['title'] for x in routes if x['target_path']==path)
